// Noir replacements for the pre-Noir text styles (S.featTitle / S.helpP / S.errBox) on the remaining pages.
const NOIR_FEAT_TITLE = { fontSize: 14, fontWeight: 600, color: FIRE.textPrimary, margin: "0 0 4px", lineHeight: 1.3 };
const NOIR_HELP = { fontSize: 12.5, lineHeight: 1.55, color: FIRE.textMuted, margin: "0 0 10px" };
// The AI call-to-action banner on Noir. Replaces { ...S.aiBanner, ...FS.cardNoir }: S.aiBanner's 4px purple-grey
// left edge survived that spread (React keeps the borderLeft longhand after the border shorthand).
const NOIR_AI_BANNER = { ...FS.cardNoir, padding: 22, marginBottom: 22, display: "flex" };
// SectionBar's label face, for hand-rolled toggles/labels that can't be a SectionBar.
const NOIR_LABEL = { fontSize: 10.5, fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", color: FIRE.textMuted, margin: 0 };
// THE AI ACCENT — one blue for every AI-drafted surface (training drill plan, recruitment plan, PR caption), so a
// leader learns "blue = drafted by the AI, review it" once. Blue is info, never good/warn/bad.
const NOIR_AI = {
  blue: "#4F90D6", blueText: "#7FB2E6", glow: "radial-gradient(130% 150% at 90% 0%, rgba(79,144,214,.14), transparent 50%)",
  chip: { display: "inline-flex", alignItems: "center", gap: 6, fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 10.5, letterSpacing: ".1em", textTransform: "uppercase", color: "#7FB2E6", background: "rgba(79,144,214,.12)", border: "1px solid rgba(79,144,214,.4)", borderRadius: 6, padding: "4px 9px" },
};
const NOIR_ERR = { marginTop: 10, fontSize: 12.5, lineHeight: 1.45, padding: "8px 11px", borderRadius: 8, background: "rgba(200,50,58,.08)", border: "1px solid rgba(200,50,58,.3)", color: FIRE.redText };
// The mocks' inset panel (.card2 surface) — sections inside an expanded card sit on this.
const NOIR_INSET = { background: FIRE.card2Noir, border: `1px solid ${FIRE.lineNoir}`, borderRadius: 10 };
// The mocks' .ck ring: "pass" = green ring + check, "fail" = red ring + X, "todo" = neutral ring (an item to check,
// not a result — a template item must never wear a green check it hasn't earned).
function CheckMark({ state = "pass", size = 18 }) {
  const ring = state === "pass" ? { background: "rgba(47,168,105,.16)", border: "1px solid rgba(47,168,105,.5)" }
    : state === "fail" ? { background: "rgba(200,50,58,.16)", border: "1px solid rgba(200,50,58,.5)" }
    : { background: "transparent", border: `1px solid ${FIRE.line2Noir}` };
  return (
    <span aria-hidden="true" style={{ width: size, height: size, borderRadius: "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...ring }}>
      {state === "pass" ? <Check size={Math.round(size * 0.6)} color={FIRE.greenText} strokeWidth={3} />
        : state === "fail" ? <X size={Math.round(size * 0.6)} color={FIRE.redBright} strokeWidth={3} />
        : <span style={{ width: 5, height: 5, borderRadius: "50%", background: FIRE.textMuted2 }} />}
    </span>
  );
}
// The mocks' .h2res result pill: pass = green, fail = red (a failed check is bad, not a warning).
function ResultBadge({ pass, children }) {
  const c = pass ? FIRE.greenText : FIRE.redText;
  return <span style={{ fontSize: 10.5, fontWeight: 700, borderRadius: 999, padding: "3px 11px", flexShrink: 0, color: c, background: pass ? "rgba(47,168,105,.10)" : "rgba(200,50,58,.10)", border: `1px solid ${pass ? "rgba(47,168,105,.4)" : "rgba(200,50,58,.4)"}`, ...FS.num }}>{children}</span>;
}
// Noir inset sub-panel (the mock's .minichart): a key swatch + Oswald title, an optional open chevron, the chart,
// and a small caption under it.
function MiniChart({ title, swatch, caption, onOpen, children }) {
  return (
    <div style={{ background: FIRE.card2Noir, border: `1px solid ${FIRE.lineNoir}`, borderRadius: 10, padding: "8px 11px 7px", minWidth: 0 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 4 }}>
        {swatch}
        <span style={{ fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 12.5, letterSpacing: ".02em", color: FIRE.textPrimary }}>{title}</span>
        {onOpen && <button onClick={onOpen} aria-label={`Open ${title}`} style={{ marginLeft: "auto", background: "none", border: "none", padding: 0, cursor: "pointer", display: "inline-flex" }}><ChevronRight size={15} color={FIRE.btnIcon} /></button>}
      </div>
      {children}
      {caption && <div style={{ fontSize: 10, color: FIRE.textMuted, marginTop: 2 }}>{caption}</div>}
    </div>
  );
}
// Red uppercase tracked label. `as="button"` for a collapsible section header.
// The mocks' .segctl as one component: a dark track, compact segments, the active one solid red.
// options = [[value, label], …]. Same pattern the inline segmented controls on Reports/Meetings/Training use.
function NoirSeg({ options, value, onChange, style }) {
  return (
    <div style={{ display: "inline-flex", flexWrap: "wrap", gap: 2, padding: 3, borderRadius: 7, background: FIRE.insetNoir, border: `1px solid ${FIRE.lineNoir}`, ...style }}>
      {options.map(([v, l]) => {
        const on = value === v;
        return <button key={String(v)} type="button" onClick={() => onChange(v)} aria-pressed={on} style={{ fontSize: 11.5, fontWeight: 600, padding: "5px 12px", borderRadius: 5, border: "none", cursor: "pointer", fontFamily: "inherit", background: on ? FIRE.redBright : "transparent", color: on ? "#fff" : FIRE.textSecondary }}>{l}</button>;
      })}
    </div>
  );
}
function SectionLabel({ as: Tag = "div", style, children, ...rest }) {
  // Inside <NoirSkin>: the SectionBar label face (muted caps, .08em) instead of the red pre-Noir kicker.
  // Callers' own overrides (colour, case, margins) still win. Outside NoirSkin unchanged.
  const base = React.useContext(NoirCtx)
    ? { fontSize: 10.5, textTransform: "uppercase", letterSpacing: ".08em", color: FIRE.textMuted, fontWeight: 700, margin: 0 }
    : FS.kicker;
  return <Tag style={{ ...base, ...style }} {...rest}>{children}</Tag>;
}
// The card surface. `as="button"` for a whole-card link; `style` for an accent edge or layout.
function Card({ as: Tag = "div", padding = "14px 16px", style, children, ...rest }) {
  const face = useCardFace();
  return <Tag style={{ ...face, padding, ...style }} {...rest}>{children}</Tag>;
}
// Big tabular number + label + optional sub-line. tone: green | amber | red | muted (default: primary text).
// onClick makes it a button with the chevron; without it it's a plain box (read-only views).
function StatTile({ label, value, sub, tone, onClick, icon: Icon }) {
  const Tag = onClick ? "button" : "div";
  const face = useCardFace();
  if (React.useContext(NoirCtx)) return (
    <Tag onClick={onClick} className={onClick ? "stat-cta" : undefined} style={{ ...face, borderRadius: 11, boxShadow: FIRE.tileShadowNoir, padding: "9px 12px", textAlign: "left", cursor: onClick ? "pointer" : "default", fontFamily: "inherit", width: "100%", display: "flex", flexDirection: "column", justifyContent: "center" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        {Icon ? <span style={{ width: 26, height: 26, borderRadius: 7, background: FIRE.insetNoir, border: `1px solid ${FIRE.lineNoir}`, display: "inline-flex", alignItems: "center", justifyContent: "center" }}><Icon size={14} color={FIRE.redText} /></span> : <span />}
        {onClick && <ChevronRight size={15} color={FIRE.btnIcon} />}
      </div>
      <div style={{ fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 25, lineHeight: 1, letterSpacing: "-.01em", color: TONE[tone] || FIRE.textPrimary, marginTop: 6, ...FS.num }}>{value}</div>
      <div style={{ fontSize: 11.5, fontWeight: 500, color: FIRE.textSecondary, marginTop: 3 }}>{label}</div>
      {sub && <div style={{ fontSize: 10.5, color: FIRE.textMuted, marginTop: 2, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{sub}</div>}
    </Tag>
  );
  return (
    <Tag onClick={onClick} className={onClick ? "stat-cta" : undefined} style={{ ...face, padding: "16px 18px", textAlign: "left", cursor: onClick ? "pointer" : "default", fontFamily: "inherit", width: "100%", position: "relative" }}>
      <div style={{ fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 34, lineHeight: 1, letterSpacing: "-.01em", color: TONE[tone] || FIRE.textPrimary, ...FS.num }}>{value}</div>
      <div style={{ fontSize: 12.5, color: FIRE.textSecondary, marginTop: 7 }}>{label}</div>
      {sub && <div style={{ fontSize: 11, color: FIRE.textMuted, marginTop: 3 }}>{sub}</div>}
      {onClick && <ChevronRight size={16} color={FIRE.btnIcon} style={{ position: "absolute", top: 14, right: 14 }} />}
    </Tag>
  );
}
function HealthDot({ tone = "green", size = 10, className, style }) {
  return <span className={className} style={{ display: "inline-block", width: size, height: size, borderRadius: 999, background: TONE[tone] || TONE.muted, flexShrink: 0, ...style }} />;
}
// Thin rounded bar on the dark track. pct is clamped to 0–100.
// size="lg": the feature version — taller, hairline-edged track, the fill a soft left-to-right ramp into the
// tone with a faint glow. Same TONE colour throughout (alpha only), so it stays on-palette.
function ProgressBar({ pct, tone = "green", size, style }) {
  const w = Math.max(0, Math.min(100, Number(pct) || 0));
  const c = TONE[tone] || TONE.green;
  const lg = size === "lg";
  return (
    <div style={{ height: lg ? 10 : 7, borderRadius: 99, background: FIRE.track, overflow: "hidden", marginTop: lg ? 8 : 5,
                  ...(lg ? { border: `0.5px solid ${FIRE.hairline}` } : null), ...style }}>
      <div style={{ height: "100%", borderRadius: 99, width: `${w}%`,
                    background: lg ? `linear-gradient(90deg, ${c}80, ${c})` : c,
                    ...(lg ? { boxShadow: `0 0 10px ${c}40` } : null) }} />
    </div>
  );
}
// One "all clear" / empty treatment. icon defaults to the green check; pass icon={null} for text only.
function EmptyState({ icon = <CheckCircle2 size={15} color={FIRE.green} />, text, style }) {
  return <div style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 13, color: FIRE.textMuted, ...style }}>{icon}{text}</div>;
}

/* ---------------- ErrorBoundary ----------------
   WHY THIS EXISTS. Twice now a single render-time TypeError has taken the entire app to a white
   screen — once from a stale lucide import, once from calling a boolean (`canManage(role)` where
   `canManage` was shadowed by a local const). Both were one wrong token in one component, and both
   cost the whole product, because an uncaught throw during render unmounts the tree.

   The lint gate added after the first one CANNOT catch the second class: no-undef checks that a
   name is DEFINED, not that it holds the type you are about to use it as. `canManage(role)` is
   perfectly well-defined and still throws. So the answer is containment, not another linter.

   BOUNDARIES MUST BE CLASSES. There is no hook equivalent — getDerivedStateFromError and
   componentDidCatch exist only on class components. This is the one class in the file, on purpose.

   WHAT IT DOES NOT CATCH, so nobody trusts it further than it goes: event handlers, async work
   (promise rejections, setTimeout), and errors thrown during SSR. React only routes errors raised
   in the render/lifecycle path here. A crash inside an onClick still goes to window.onerror. */
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) {
    // The component stack is the part that actually locates the bug — it names the component that
    // threw, which the message alone does not. Kept on console.error so it lands in Vercel logs
    // and in whatever the member's browser console captures for a bug report.
    console.error("[ErrorBoundary]", error, info?.componentStack);
  }
  render() {
    if (!this.state.error) return this.props.children;
    return (
      <div style={{ ...FS.cardNoir, padding: "22px 24px", maxWidth: 620 }}>
        <div style={{ fontFamily: DISPLAY_FONT, fontSize: 20, fontWeight: 700, color: FIRE.textPrimary, marginBottom: 8 }}>Something went wrong on this page.</div>
        <div style={{ fontSize: 14, color: FIRE.textSecondary, lineHeight: 1.55, marginBottom: 16 }}>
          This section hit an unexpected error. Your data is safe. Try reloading, or pick another section from the menu.
        </div>
        <button style={FS.btnPrimary} onClick={() => window.location.reload()}>Reload</button>
        {/* Collapsed, not hidden. A member does not need to read a stack trace, but "it says
            something about canManage" is the single most useful thing they can put in a bug
            report — so it stays one tap away rather than console-only. */}
        <details style={{ marginTop: 14 }}>
          <summary style={{ fontSize: 12, color: FIRE.textMuted, cursor: "pointer" }}>Technical details</summary>
          <div style={{ fontSize: 12, color: FIRE.textMuted, marginTop: 6, fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", wordBreak: "break-word" }}>
            {String(this.state.error?.message || this.state.error)}
          </div>
        </details>
      </div>
    );
  }
}

