function statusOf(m, t) {
  if (m >= t * 2) return { label: "OVERDUE", color: "#B11E2A" };
  if (m >= t) return { label: "DUE NOW", color: "#E0A100" };
  return { label: "CURRENT", color: "#2E7D52" };
}

