const CRISIS_TAG = { fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: "#fff", background: FIRE.redBright, borderRadius: 999, padding: "2px 8px", whiteSpace: "nowrap" };
const WELLNESS_TAG = { fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: FIRE.amberText, background: FIRE.card2Noir, border: `1px solid ${FIRE.amberText}55`, borderRadius: 999, padding: "2px 8px", whiteSpace: "nowrap" };
const telDigits = (p) => String(p || "").replace(/[^\d+]/g, "");   // tel:/sms: want digits (keep a leading +)
// Only the contact methods a resource actually has, as tappable actions (real dial/text/compose on a phone).
function ResourceActions({ r, compact }) {
  // Labeled buttons (full-width contexts: the Reach-out modal). Icon-only (compact) for grid tiles.
  const labelBtn = (href, Icon, label) => (
    <a key={label} href={href} target={href.startsWith("http") ? "_blank" : undefined} rel="noopener noreferrer"
       style={{ ...YS_ACTION_BTN, background: FIRE.card2Noir, color: FIRE.btnText, border: `1px solid ${FIRE.line2Noir}` }}>
      <Icon size={14} color={FIRE.btnIcon} /> {label}
    </a>
  );
  const iconBtn = (href, Icon, label) => (
    <a key={label} href={href} target={href.startsWith("http") ? "_blank" : undefined} rel="noopener noreferrer" title={label} aria-label={label}
       style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 42, height: 36, borderRadius: 8, background: FIRE.card2Noir, border: `1px solid ${FIRE.line2Noir}`, textDecoration: "none" }}>
      <Icon size={16} color={FIRE.btnIcon} />
    </a>
  );
  const b = compact ? iconBtn : labelBtn;
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8 }}>
      {r.phone       && b(`tel:${telDigits(r.phone)}`,       Phone,         "Call")}
      {r.text_number && b(`sms:${telDigits(r.text_number)}`, MessageSquare, "Text")}
      {r.address     && b(mapsHref(r.address),               MapPin,        "Directions")}
      {r.website     && b(r.website,                          Globe,         "Website")}
      {r.email       && b(`mailto:${r.email}`,                Mail,          "Email")}
    </div>
  );
}
/* A resource's brand mark. An uploaded image wins when the row carries one (resources has no image column today —
   adding one is a schema change, not part of this reskin); otherwise a monogram tile. NATIONAL organisations get a
   NEUTRAL steel mark — never their real logo (trademark: no national-org logos without usage rights). Crisis lines
   get the life-buoy; local rows the station red; businesses amber. */
function ResourceMark({ r, size = 34 }) {
  const initials = String(r?.name || "?").replace(/[^A-Za-z0-9 ]/g, " ").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase() || "?";
  const tone = r?.is_crisis ? FIRE.redText : r?.is_national ? "#8C9AAB" : r?.is_business ? FIRE.amberText : FIRE.redBright;
  const box = { width: size, height: size, borderRadius: 9, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden",
                background: `${tone}1F`, border: `1px solid ${tone}55` };
  if (r?.logo_url) return <span style={box}><img src={r.logo_url} alt="" style={{ width: "100%", height: "100%", objectFit: "contain" }} /></span>;
  if (r?.is_crisis) return <span style={box}><LifeBuoy size={Math.round(size * 0.5)} color={tone} /></span>;
  return <span style={{ ...box, fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: Math.round(size * 0.38), letterSpacing: ".02em", color: tone }} aria-hidden="true">{initials}</span>;
}
const YS_BLANK_FORM = { name: "", category: "", description: "", phone: "", text_number: "", website: "", email: "", address: "", is_wellness: false };
const SPONSOR_TAG = { fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: "#111", background: FIRE.amberText, borderRadius: 999, padding: "2px 8px", whiteSpace: "nowrap" };
// COMPACT CARD SIZING — the ONE source of truth for every Your Six card (crisis / health / business /
// the "Your person" picker). Change these three to resize them all at once. Spread ...YS_CARD after ...FS.card.
const YS_CARD       = { padding: "11px 14px", marginBottom: 8 };
const YS_CARD_NAME  = { fontSize: 14, fontWeight: 700, color: FIRE.textPrimary };
const YS_ACTION_BTN = { display: "inline-flex", alignItems: "center", gap: 5, padding: "8px 12px", borderRadius: 9, fontSize: 12.5, fontWeight: 700, textDecoration: "none", fontFamily: "inherit" };   // ~34px tall, tappable
// Deck/grid layout: cards tile side-by-side within each section (~2-up on a phone, more on desktop).
const YS_GRID = { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 8 };
const YS_TILE_EDIT_BTN = { display: "inline-flex", alignItems: "center", justifyContent: "center", width: 26, height: 24, borderRadius: 6, background: FIRE.card2Noir, border: `1px solid ${FIRE.line2Noir}`, cursor: "pointer", padding: 0 };
// One "Directions" link, no chooser: open the device's likely default — Apple Maps on iOS/iPadOS,
// Google Maps on Android/desktop. Address is URL-encoded so spaces/commas survive (space->%20, comma->%2C).
const mapsHref = (addr) => {
  const q = encodeURIComponent(addr);
  const ua = (typeof navigator !== "undefined" && navigator.userAgent) || "";
  const isApple = /iPad|iPhone|iPod/.test(ua) || (ua.includes("Macintosh") && (typeof navigator !== "undefined" ? navigator.maxTouchPoints || 0 : 0) > 1);   // iPadOS 13+ masquerades as Macintosh + touch
  return isApple ? `https://maps.apple.com/?q=${q}` : `https://maps.google.com/?q=${q}`;
};
function YourSix({ S, role, meId, members, notify }) {
  const canDeleteShared = useCanDeleteShared();   // Dept Admin / Project Admin only — see src/ConfirmDestructive.jsx

  const canManage = hasAny(role, CANMANAGE_ROLES);   // add/edit/remove local resources — is_canmanage() (Board/DA/Officer), mirrors the RLS
  const [resources, setResources] = useState(null);   // null = loading
  const [editMode, setEditMode] = useState(false);    // false = calm read-only; true = reveal Add + per-local-row Edit/Remove
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [busy, setBusy] = useState(false);
  const [form, setForm] = useState(YS_BLANK_FORM);
  const [formKind, setFormKind] = useState("resource");   // 'resource' | 'business' — drives which fields the form shows
  const [loadErr, setLoadErr] = useState(false);
  function load() {   // a failed READ is not "no resources" — keep last-known, flag it, recover on reconnect
    supabase.from("resources").select("*").then(({ data, error }) => {
      if (error || !data) { setLoadErr(true); return; }
      setLoadErr(false); setResources(data);
    });
  }   // dept-scoped by RLS
  useEffect(() => { load(); }, []);
  useReconnect(() => { if (loadErr) load(); });
  const [reachOpen, setReachOpen] = useState(false);
  const [reachPersonId, setReachPersonId] = useState(null);   // this member's chosen reach_out person (self-read)
  useEffect(() => { if (!meId) return; let off = false; supabase.from("members").select("reach_out_member_id").eq("id", meId).single().then(({ data }) => { if (!off) setReachPersonId(data?.reach_out_member_id || null); }); return () => { off = true; }; }, [meId]);
  useEffect(() => { if (!reachOpen) return; const onKey = (e) => { if (e.key === "Escape") setReachOpen(false); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, [reachOpen]);
  function toggleEditMode() { setEditMode((v) => { if (v) { setAdding(false); setEditingId(null); setForm(YS_BLANK_FORM); } return !v; }); }   // leaving edit mode discards half-finished edits
  function cancelForm() { setAdding(false); setEditingId(null); setForm(YS_BLANK_FORM); }
  function startEdit(r) { setAdding(false); setEditingId(r.id); setFormKind(r.is_business ? "business" : "resource"); setForm({ name: r.name || "", category: r.category || "", description: r.description || "", phone: r.phone || "", text_number: r.text_number || "", website: r.website || "", email: r.email || "", address: r.address || "", is_wellness: !!r.is_wellness }); }
  function beginAddWellness() { setEditMode(true); setEditingId(null); setFormKind("resource"); setForm({ ...YS_BLANK_FORM, category: "Department wellness", is_wellness: true }); setAdding(true); }
  function beginAddBusiness() { setEditingId(null); setFormKind("business"); setForm({ ...YS_BLANK_FORM }); setAdding(true); }
  async function addResource() {
    const isBiz = formKind === "business";
    const name = form.name.trim();
    const category = isBiz ? "Businesses who support us" : form.category.trim();   // businesses live in their own bottom section; category fixed
    if (!name || !category) { notify({ kind: "error", title: isBiz ? "Name required" : "Name and category required", text: isBiz ? "Give the business a name." : "Give the resource a name and a category." }); return; }
    setBusy(true);
    const { data: deptId, error: deptErr } = await supabase.rpc("my_department_id");
    if (deptErr || !deptId) { setBusy(false); notify({ kind: "error", title: "Couldn't find your department", text: "Please try again." }); return; }
    const nextOrder = (resources || []).filter((r) => isBiz ? r.is_business : (r.category === category && !r.is_business)).reduce((m, r) => Math.max(m, r.sort_order ?? 0), -1) + 1;
    const { error } = await supabase.from("resources").insert({
      department_id: deptId, category, name,
      description: form.description.trim() || null,
      phone: form.phone.trim() || null,
      text_number: isBiz ? null : (form.text_number.trim() || null),
      website: form.website.trim() || null,
      email: form.email.trim() || null,
      address: isBiz ? (form.address.trim() || null) : null,
      is_national: false, is_crisis: false, is_business: isBiz,
      is_wellness: isBiz ? false : form.is_wellness,
      sort_order: nextOrder, created_by: meId,
    });
    setBusy(false);
    if (error) { notify({ kind: "error", title: isBiz ? "Couldn't add the business" : "Couldn't add the resource", text: "Something went wrong. Please try again.", details: error.message }); return; }
    cancelForm(); load();
  }
  async function saveEdit(id) {
    const isBiz = formKind === "business";
    const name = form.name.trim(), category = form.category.trim();
    if (!name || (!isBiz && !category)) { notify({ kind: "error", title: isBiz ? "Name required" : "Name and category required", text: "Please fill the required fields." }); return; }
    const upd = { name, description: form.description.trim() || null, phone: form.phone.trim() || null, website: form.website.trim() || null, email: form.email.trim() || null };
    if (isBiz) { upd.address = form.address.trim() || null; }
    else { upd.category = category; upd.text_number = form.text_number.trim() || null; upd.is_wellness = form.is_wellness; }
    setBusy(true);
    const { data, error } = await supabase.from("resources").update(upd).eq("id", id).select();
    setBusy(false);
    if (error || !data || data.length === 0) { notify({ kind: "error", title: "Couldn't save", text: "Something went wrong updating that. Please try again.", details: error?.message }); return; }   // 0-row = RLS blocked a national/sponsor row
    cancelForm(); load();
  }
  async function removeResource(r) {
    if (!(await confirmDestructive({ noun: "resource", name: r.name }))) return;
    const { data, error } = await supabase.from("resources").delete().eq("id", r.id).select();
    if (error || !data || data.length === 0) { notify({ kind: "error", title: "Couldn't remove the resource", text: "Something went wrong. Please try again.", details: error?.message }); return; }
    load();
  }
  const allCategories = [...new Set((resources || []).map((r) => r.category))].sort();
  const hasWellness = (resources || []).some((r) => r.is_wellness);
  // Add/Edit form (shared) — bound to `form`.
  const formCard = (onSave, saveLabel) => {
    const isBiz = formKind === "business";
    return (
    <Card padding={12} style={{ background: FIRE.card2Noir, marginBottom: 10, display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <label style={{ ...S.field, flex: 1, minWidth: 160 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Name</span><input style={FS.input} value={form.name} placeholder={isBiz ? "e.g. Miller's Hardware" : "e.g. Chaplain Dave, or Peer support"} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
        {!isBiz && <label style={{ ...S.field, minWidth: 160 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Category</span><input style={FS.input} list="ys-cats" value={form.category} placeholder="e.g. Department wellness" onChange={(e) => setForm((f) => ({ ...f, category: e.target.value }))} /><datalist id="ys-cats">{allCategories.map((c) => <option key={c} value={c} />)}</datalist></label>}
      </div>
      <label style={S.field}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>{isBiz ? "What they do / how they support us (optional)" : "Description (optional)"}</span><textarea style={{ ...FS.input, minHeight: 44, resize: "vertical" }} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} /></label>
      {isBiz && <label style={S.field}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Address (tap-to-map, optional)</span><input style={FS.input} value={form.address} placeholder="123 Main St, Yourtown" onChange={(e) => setForm((f) => ({ ...f, address: e.target.value }))} /></label>}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <label style={{ ...S.field, flex: 1, minWidth: 130 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Phone (call)</span><input style={FS.input} value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
        {!isBiz && <label style={{ ...S.field, flex: 1, minWidth: 130 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Text number</span><input style={FS.input} value={form.text_number} onChange={(e) => setForm((f) => ({ ...f, text_number: e.target.value }))} /></label>}
        <label style={{ ...S.field, flex: 1, minWidth: 130 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Website</span><input style={FS.input} value={form.website} placeholder="https://" onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))} /></label>
        <label style={{ ...S.field, flex: 1, minWidth: 130 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Email</span><input style={FS.input} value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
      </div>
      {!isBiz && <label style={{ display: "inline-flex", alignItems: "center", gap: 8, fontSize: 13, color: FIRE.textSecondary, cursor: "pointer" }}>
        <input type="checkbox" checked={form.is_wellness} onChange={(e) => setForm((f) => ({ ...f, is_wellness: e.target.checked }))} />
        Department wellness contact — a real person members can reach in the “Reach out” flow
      </label>}
      <div style={{ display: "flex", gap: 8 }}>
        <button style={{ ...FS.btnPrimary, opacity: busy ? 0.6 : 1 }} disabled={busy} onClick={onSave}>{busy ? <><Loader2 size={15} className="spin" /> Saving…</> : <><CheckCircle2 size={15} /> {saveLabel}</>}</button>
        <button style={FS.btn} onClick={cancelForm} disabled={busy}>Cancel</button>
      </div>
    </Card>
  ); };
  // ONE card language for every resource (crisis / health / business). Crisis gets a small CALM accent
  // (thin left border + LifeBuoy) so it's findable without shouting; national vs local vs sponsor and the
  // edit-mode lock all live on the same small card. Inline-edit swaps the card for the form.
  // A grid TILE (~half-width on a phone): name + tags on top, short (2-line) description, icon actions below.
  // Untagged = national (noise to a member); only "Your station"/"Platform sponsor"/"Wellness" show. The edit
  // form spans the full grid width (gridColumn 1/-1) so it isn't squeezed into a narrow cell.
  const renderCard = (r) => {
    if (editingId === r.id) return <div key={r.id} style={{ gridColumn: "1 / -1" }}>{formCard(() => saveEdit(r.id), "Save changes")}</div>;
    const localTag = !r.is_business && !r.is_national;
    const sponsorTag = r.is_business && r.is_national;
    const hasTag = localTag || sponsorTag || r.is_wellness;
    return (
      <div key={r.id} style={{ ...FS.cardNoir, ...YS_CARD, marginBottom: 0, display: "flex", flexDirection: "column", ...(r.is_crisis ? { borderLeft: `3px solid ${FIRE.redText}` } : {}), ...(editMode && !r.is_national ? { borderStyle: "dashed" } : {}) }}>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 9 }}>
          <ResourceMark r={r} />
          <span style={{ ...YS_CARD_NAME, flex: 1, minWidth: 0, lineHeight: 1.25, alignSelf: "center" }}>{r.name}</span>
          {editMode && canManage && (r.is_national
            ? <span title={r.is_business ? "Platform sponsor — locked" : "Verified national resource — locked"} style={{ flexShrink: 0, display: "inline-flex", marginTop: 2 }}><Lock size={13} color={FIRE.textMuted2} /></span>
            : <span style={{ display: "inline-flex", gap: 4, flexShrink: 0 }}>
                <button title="Edit" style={YS_TILE_EDIT_BTN} onClick={() => startEdit(r)}><Pencil size={12} color={FIRE.textSecondary} /></button>
                {canDeleteShared && <button title="Remove" style={YS_TILE_EDIT_BTN} onClick={() => removeResource(r)}><X size={12} color={FIRE.deleteRed} /></button>}
              </span>)}
        </div>
        {hasTag && <div style={{ display: "flex", gap: 5, flexWrap: "wrap", marginTop: 5 }}>
          {localTag && <span style={LOCAL_TAG}>Your station</span>}
          {sponsorTag && <span style={SPONSOR_TAG}>Platform sponsor</span>}
          {r.is_wellness && <span style={WELLNESS_TAG}>Wellness</span>}
        </div>}
        {r.description && <div style={{ fontSize: 12, color: FIRE.textSecondary, marginTop: 5, lineHeight: 1.35, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{r.description}</div>}
        <ResourceActions r={r} compact />
      </div>
    );
  };
  const crisisItems = (resources || []).filter((r) => r.is_crisis).sort((a, b) => (a.is_national ? 1 : 0) - (b.is_national ? 1 : 0) || (a.sort_order - b.sort_order));
  // Reach-out flow layers (in order): your person -> wellness contacts -> crisis lines (always seeded => never empty).
  const reachPerson = reachPersonId ? (members || []).find((m) => m.id === reachPersonId && m.phone) : null;   // only if they have a number
  const wellnessContacts = (resources || []).filter((r) => r.is_wellness && r.phone);
  // ORDERING (B) — the ONE place to change business sort: national/platform sponsors PINNED TOP, then local businesses local-first.
  const businessItems = (resources || []).filter((r) => r.is_business).sort((a, b) => (b.is_national ? 1 : 0) - (a.is_national ? 1 : 0) || (a.sort_order - b.sort_order) || a.name.localeCompare(b.name));
  const groups = useMemo(() => {
    const byCat = new Map();
    (resources || []).filter((r) => !r.is_crisis && !r.is_business).forEach((r) => { if (!byCat.has(r.category)) byCat.set(r.category, []); byCat.get(r.category).push(r); });
    const cats = [...byCat.keys()].sort((a, b) => {
      const ia = RESOURCE_CATEGORY_ORDER.indexOf(a), ib = RESOURCE_CATEGORY_ORDER.indexOf(b);
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || a.localeCompare(b);
    });
    // within a category: LOCAL first, national second, then sort_order
    return cats.map((cat) => ({ cat, items: byCat.get(cat).sort((a, b) => (a.is_national ? 1 : 0) - (b.is_national ? 1 : 0) || (a.sort_order - b.sort_order) || a.name.localeCompare(b.name)) }));
  }, [resources]);
  return (
    <PageShell band watermark="SIX" kicker="YOUR SIX" title={<>Support &amp; resources</>}
      sub="Help is here when you need it — for you, or someone on your crew. Every line below is real and answered."
      actions={canManage && resources && (
          <button onClick={toggleEditMode} style={{ ...FS.btn, marginTop: 6, display: "inline-flex", alignItems: "center", gap: 5, ...(editMode ? { borderColor: FIRE.redBright, color: FIRE.textPrimary } : {}) }}>
            {editMode ? <><CheckCircle2 size={14} color={FIRE.green} /> Done</> : <><Pencil size={14} color={FIRE.btnIcon} /> Edit resources</>}
          </button>
        )}>
      <NoirSkin>
      {resources === null ? (
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: FIRE.textMuted }}><Loader2 size={14} className="spin" /> Loading…</div>
      ) : (<>
        {/* Reach out — calm invitation (not an alarm), pinned at top. Opens the ordered flow. */}
        <button onClick={() => setReachOpen(true)} style={{ ...FS.cardNoir, ...YS_CARD, width: "100%", display: "flex", alignItems: "center", gap: 10, cursor: "pointer", textAlign: "left", fontFamily: "inherit", border: `1px solid ${FIRE.greenText}44`, borderLeft: `3px solid ${FIRE.greenText}` }}>
          <HeartHandshake size={22} color={FIRE.greenText} style={{ flexShrink: 0 }} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontFamily: DISPLAY_FONT, fontSize: 17, fontWeight: 700, letterSpacing: ".02em", color: FIRE.textPrimary }}>Reach out</div>
            <div style={{ fontSize: 12.5, color: FIRE.textSecondary, lineHeight: 1.35 }}>Talk to someone — your person, a wellness contact, or a 24/7 line.</div>
          </div>
          <ChevronRight size={18} color={FIRE.btnIcon} style={{ flexShrink: 0 }} />
        </button>
        {reachOpen && createPortal(
          <div onClick={() => setReachOpen(false)} style={{ position: "fixed", inset: 0, background: "rgba(8,10,16,.72)", zIndex: 120, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "40px 16px", overflowY: "auto" }}>
            <div onClick={(e) => e.stopPropagation()} style={{ ...NOIR_MODAL_PANEL, background: `radial-gradient(120% 60% at 92% 0%, rgba(200,50,58,.12), transparent 40%), ${NOIR_MODAL_PANEL.background}`, maxWidth: 460, width: "100%", padding: "18px 18px calc(18px + env(safe-area-inset-bottom))" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                <HeartHandshake size={20} color={FIRE.greenText} />
                <div style={{ flex: 1, fontFamily: "'Oswald', system-ui, sans-serif", fontSize: 20, fontWeight: 700, color: FIRE.textPrimary }}>Reach out</div>
                <button onClick={() => setReachOpen(false)} title="Close (Esc)" style={{ ...FS.btn, padding: "6px 8px" }}><X size={16} color={FIRE.btnIcon} /></button>
              </div>
              <div style={{ fontSize: 13, color: FIRE.textSecondary, lineHeight: 1.45, marginBottom: 14 }}>You don't have to carry it alone. Start with a person — a 24/7 line is always here too.</div>
              {reachPerson && (<>
                <SectionLabel style={{ textTransform: "none", letterSpacing: "normal", marginBottom: 6 }}>Your person</SectionLabel>
                <Card padding={0} style={{ ...YS_CARD, borderLeft: `3px solid ${FIRE.greenText}` }}>
                  <div style={YS_CARD_NAME}>{reachPerson.name}</div>
                  <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginTop: 8 }}>
                    <a href={`tel:${telDigits(reachPerson.phone)}`} style={{ ...YS_ACTION_BTN, background: FIRE.green, color: "#fff", border: "none" }}><Phone size={14} color="#fff" /> Call {reachPerson.name.split(" ")[0]}</a>
                  </div>
                </Card>
              </>)}
              {wellnessContacts.length > 0 && (<>
                <SectionLabel style={{ textTransform: "none", letterSpacing: "normal", margin: reachPerson ? "12px 0 6px" : "0 0 6px" }}>Department wellness contacts</SectionLabel>
                {wellnessContacts.map((r) => (
                  <div key={r.id} style={{ ...FS.cardNoir, ...YS_CARD, borderLeft: `3px solid ${FIRE.greenText}` }}>
                    <div style={YS_CARD_NAME}>{r.name}</div>
                    {r.description && <div style={{ fontSize: 12.5, color: FIRE.textSecondary, marginTop: 2, lineHeight: 1.4 }}>{r.description}</div>}
                    <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginTop: 8 }}>
                      <a href={`tel:${telDigits(r.phone)}`} style={{ ...YS_ACTION_BTN, background: FIRE.green, color: "#fff", border: "none" }}><Phone size={14} color="#fff" /> Call</a>
                      {r.text_number && <a href={`sms:${telDigits(r.text_number)}`} style={{ ...YS_ACTION_BTN, background: FIRE.card2Noir, color: FIRE.btnText, border: `1px solid ${FIRE.line2Noir}` }}><MessageSquare size={14} color={FIRE.btnIcon} /> Text</a>}
                    </div>
                  </div>
                ))}
              </>)}
              {/* Crisis lines — always seeded, so the flow is NEVER empty. Calm, below the people. */}
              <SectionLabel style={{ textTransform: "none", letterSpacing: "normal", margin: (reachPerson || wellnessContacts.length) ? "12px 0 6px" : "0 0 6px", display: "inline-flex", alignItems: "center", gap: 6 }}><LifeBuoy size={12} color={FIRE.redText} /> Crisis lines · 24/7</SectionLabel>
              {crisisItems.map((r) => (
                <div key={r.id} style={{ ...FS.cardNoir, ...YS_CARD, borderLeft: `3px solid ${FIRE.redText}` }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}><LifeBuoy size={13} color={FIRE.redText} style={{ flexShrink: 0 }} /><span style={YS_CARD_NAME}>{r.name}</span></div>
                  <ResourceActions r={r} />
                </div>
              ))}
            </div>
          </div>,
          document.body
        )}
        {/* Crisis lines: same unified card as everywhere, calm accent, at top so they're findable. */}
        {crisisItems.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <CardHead icon={LifeBuoy} title="Support lines · always here" />
            <div style={YS_GRID}>{crisisItems.map(renderCard)}</div>
          </div>
        )}
        {/* Gentle nudge: set the department's wellness contacts so members can reach a real person. */}
        {canManage && !hasWellness && (
          <Card padding="14px 16px" style={{ marginBottom: 16, borderLeft: `3px solid ${FIRE.amberText}` }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: FIRE.textPrimary, marginBottom: 4 }}>Add your department's wellness contacts</div>
            <div style={{ fontSize: 13, color: FIRE.textSecondary, lineHeight: 1.45, marginBottom: 10 }}>These are your crew's real people — a chaplain, a peer supporter, an officer — who members can reach when they're struggling. They appear first in the “Reach out” flow, so a member always reaches a person before a hotline.</div>
            <button style={{ ...FS.btn, display: "inline-flex", alignItems: "center", gap: 6 }} onClick={beginAddWellness}><Plus size={14} color={FIRE.btnIcon} /> Add a wellness contact</button>
          </Card>
        )}
        {editMode && (   /* edit mode only ever turns on from the leaders-only Edit button */
          <div style={{ ...NOIR_INSET, padding: "9px 12px", marginBottom: 12, display: "flex", alignItems: "center", gap: 9, borderColor: `${FIRE.amberText}55` }}>
            <Pencil size={14} color={FIRE.amberText} style={{ flexShrink: 0 }} />
            <span style={{ fontSize: 12.5, color: FIRE.textSecondary, lineHeight: 1.4 }}>Editing — your station's own entries (dashed) can be changed. National lines and platform sponsors are locked.</span>
          </div>
        )}
        {/* Edit mode: panel-level Add (resources). */}
        {canManage && editMode && (adding && formKind === "resource" ? formCard(addResource, "Add resource") : (
          <button style={{ ...FS.btn, marginBottom: 12, display: "inline-flex", alignItems: "center", gap: 6 }} onClick={() => { setEditingId(null); setFormKind("resource"); setForm(YS_BLANK_FORM); setAdding(true); }}><Plus size={15} color={FIRE.btnIcon} /> Add resource</button>
        ))}
        {groups.length === 0 && crisisItems.length === 0 ? (
          <Card padding={24} style={{ color: FIRE.textMuted, fontSize: 14 }}>No resources yet.</Card>
        ) : groups.map(({ cat, items }) => (
          <div key={cat} style={{ marginBottom: 14 }}>
            <CardHead icon={BookOpen} title={cat} />
            <div style={YS_GRID}>{items.map(renderCard)}</div>
          </div>
        ))}
        {/* Businesses who support us — bottom section. Sponsors (national) pinned top per ordering (B). */}
        {(businessItems.length > 0 || (canManage && editMode)) && (
          <div style={{ marginTop: 4, marginBottom: 18 }}>
            <CardHead icon={Briefcase} title="Businesses who support us" />
            {canManage && editMode && (adding && formKind === "business" ? formCard(addResource, "Add business") : (
              <button style={{ ...FS.btn, marginBottom: 10, display: "inline-flex", alignItems: "center", gap: 6 }} onClick={beginAddBusiness}><Plus size={14} color={FIRE.btnIcon} /> Add business</button>
            ))}
            {businessItems.length === 0 && !(adding && formKind === "business") && <div style={{ fontSize: 13, color: FIRE.textMuted, marginBottom: 6 }}>No supporter businesses yet{canManage ? " — add the local businesses that back your department." : "."}</div>}
            <div style={YS_GRID}>{businessItems.map(renderCard)}</div>
          </div>
        )}
      </>)}
      </NoirSkin>
    </PageShell>
  );
}
// Member's optional "reach out" person — private, self-only. Reads the current value via a
// self-read (RLS allows a member to read their own row); writes via the tightly-scoped
// set_reach_out_person RPC (own row + reach_out_member_id column only).
function ReachOutPersonPicker({ S, members, meId, notify }) {
  const [current, setCurrent] = useState(undefined);   // undefined = loading, null = none, uuid = set
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    let off = false;
    supabase.from("members").select("reach_out_member_id").eq("id", meId).single()
      .then(({ data }) => { if (!off) setCurrent(data ? (data.reach_out_member_id || null) : null); });
    return () => { off = true; };
  }, [meId]);
  const options = (members || []).filter((m) => isAssignable(m) && m.id !== meId).sort((a, b) => (a.name || "").localeCompare(b.name || ""));
  const person = current ? (members || []).find((m) => m.id === current) : null;
  async function choose(val) {
    const target = val || null;
    setSaving(true);
    const { error } = await supabase.rpc("set_reach_out_person", { p_target: target });
    setSaving(false);
    if (error) { notify({ kind: "error", title: "Couldn't save that", text: error.message || "Please try again." }); return; }
    setCurrent(target);
    notify({ kind: "success", text: target ? "Your person is set." : "Cleared your person." });
  }
  const [picking, setPicking] = useState(false);   // the crew list is open (always open when nobody is chosen)
  const [q, setQ] = useState("");
  const shown = options.filter((m) => !q.trim() || (m.name || "").toLowerCase().includes(q.trim().toLowerCase()));
  const initials = (n) => String(n || "?").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase();
  const avatar = (m, size = 40, tone = FIRE.greenText) => (
    <span aria-hidden="true" style={{ width: size, height: size, borderRadius: 999, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: Math.round(size * 0.36), color: tone, background: `${tone}1A`, border: `1px solid ${tone}55` }}>{initials(m?.name)}</span>
  );
  const listOpen = current === null || picking;
  return (
    <PageShell band watermark="PERSON" kicker="YOUR PERSON" title="Who's your person?"
      sub="Optional. Someone on your crew you'd want to hear from in a hard moment — they become the first tap in “Reach out” on Your Six.">
      <NoirSkin>
      <div style={{ ...NOIR_INSET, padding: "10px 13px", marginBottom: 12, display: "flex", alignItems: "center", gap: 9 }}>
        <Lock size={14} color={FIRE.greenText} style={{ flexShrink: 0 }} />
        <span style={{ fontSize: 12.5, color: FIRE.textSecondary, lineHeight: 1.4 }}><b style={{ color: FIRE.textPrimary }}>Private to you.</b> Only you can see or change this.</span>
      </div>
      {current === undefined ? (
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: FIRE.textMuted }}><Loader2 size={14} className="spin" /> Loading…</div>
      ) : (<>
        {person && (
          <div style={{ ...FS.cardNoir, padding: "14px 16px", marginBottom: 12, borderLeft: `3px solid ${FIRE.greenText}` }}>
            <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".1em", textTransform: "uppercase", color: FIRE.textMuted, marginBottom: 8 }}>Your person</div>
            <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              {avatar(person, 46)}
              <div style={{ flex: 1, minWidth: 140 }}>
                <div style={{ fontSize: 16, fontWeight: 700, color: FIRE.textPrimary }}>{person.name}</div>
                <div style={{ fontSize: 12.5, color: FIRE.textMuted, ...FS.num }}>{person.phone || "No number on file"}</div>
              </div>
              {person.phone && <a href={`tel:${telDigits(person.phone)}`} style={{ ...YS_ACTION_BTN, background: FIRE.green, color: "#fff", border: "none" }}><Phone size={14} color="#fff" /> Call</a>}
              {person.phone && <a href={`sms:${telDigits(person.phone)}`} style={{ ...YS_ACTION_BTN, background: FIRE.card2Noir, color: FIRE.btnText, border: `1px solid ${FIRE.line2Noir}` }}><MessageSquare size={14} color={FIRE.btnIcon} /> Text</a>}
              <button type="button" disabled={saving} onClick={() => setPicking((v) => !v)} style={{ ...YS_ACTION_BTN, background: "transparent", color: FIRE.textSecondary, border: `1px solid ${FIRE.line2Noir}`, cursor: "pointer" }}>{picking ? "Keep" : "Change"}</button>
            </div>
            {!person.phone && <div style={{ marginTop: 10, fontSize: 12.5, color: FIRE.amberText }}>This person has no number on file, so “Reach out” can't call them yet — pick someone with a number, or ask an officer to add theirs.</div>}
          </div>
        )}
        {current && !person && (
          <div style={{ ...NOIR_INSET, padding: "10px 13px", marginBottom: 12, fontSize: 12.5, color: FIRE.amberText }}>The person you picked is no longer on the active roster. Choose someone else, or clear it.</div>
        )}
        {listOpen && (
          <div style={{ ...FS.cardNoir, padding: "12px 14px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
              <span style={{ fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 15, color: FIRE.textPrimary, flex: 1 }}>Pick from your crew</span>
              {options.length > 8 && <input style={{ ...FS.input, maxWidth: 220, padding: "7px 10px", fontSize: 13 }} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Find someone…" aria-label="Find someone on your crew" />}
            </div>
            {shown.length === 0 && <div style={{ fontSize: 13, color: FIRE.textMuted, padding: "6px 0" }}>{options.length ? "No one matches that." : "No one else on the roster yet."}</div>}
            {shown.map((m) => {
              const on = m.id === current;
              return (
                <button key={m.id} type="button" disabled={saving || !m.phone || on} onClick={() => { setPicking(false); choose(m.id); }}
                  style={{ width: "100%", display: "flex", alignItems: "center", gap: 11, padding: "9px 6px", background: on ? FIRE.card2Noir : "transparent", border: "none", borderBottom: `1px solid ${FIRE.lineNoir}`, cursor: !m.phone || on ? "default" : "pointer", fontFamily: "inherit", textAlign: "left", opacity: m.phone ? 1 : 0.5 }}>
                  {avatar(m, 32, m.phone ? FIRE.textSecondary : FIRE.textMuted)}
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ display: "block", fontSize: 13.5, fontWeight: 600, color: FIRE.textPrimary }}>{m.name}</span>
                    {!m.phone && <span style={{ display: "block", fontSize: 11.5, color: FIRE.textMuted }}>No number on file</span>}
                  </span>
                  {on ? <CheckCircle2 size={16} color={FIRE.greenText} /> : m.phone ? <ChevronRight size={15} color={FIRE.btnIcon} /> : null}
                </button>
              );
            })}
            {current && <button type="button" disabled={saving} onClick={() => { setPicking(false); choose(""); }} style={{ ...FS.btn, marginTop: 10, padding: "6px 11px", fontSize: 12 }}>Clear — no person</button>}
          </div>
        )}
        {saving && <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, color: FIRE.textMuted, marginTop: 8 }}><Loader2 size={13} className="spin" /> Saving…</div>}
      </>)}
      </NoirSkin>
    </PageShell>
  );
}
/* ── Automatic station presence: the prominent disclosure ────────────────────────────────
   Shown BEFORE any OS permission prompt, which is both a Play Store requirement for
   background location and the only honest order to do it in: the system dialog asks
   "allow all the time?" without ever explaining what for, and a member cannot agree to
   something nobody described.

   G4b IS THIS SCREEN AND NOTHING ELSE. No plugin call, no OS prompt, no geofence. The
   buttons record an answer and stop. G4c reads that answer and does the native work.

   Written as a plain panel rather than a modal on purpose. Consent is not a thing to
   dismiss with an X — it belongs in Settings where a member can re-read it later, and
   G4c can mount this same panel inside an overlay for the first-run pass without the
   copy having to be written twice. */

/* Owner-supplied copy, aligned to APP-002 Background Location Policy. RENDERED VERBATIM.
   Do not reword, re-split or "tighten" any of it: this is the text a member is agreeing
   to, and an edit made for rhythm is an edit to what we promised. Every sentence is also
   a commitment the code has to keep — if the behaviour changes, this changes with it, or
   we are misleading the person consenting.

   The one presentational decision: `lead` renders in a set-apart callout rather than the
   body flow, because it carries the "even when the app is closed or not in use" statement
   that Play requires to be conspicuous. That is emphasis, not rewording. */
const GEOFENCE_DISCLOSURE = {
  title: "Automatic station presence",
  lead: "B4C can automatically record when you arrive at and leave your department's approved locations — even when the app is closed or not in use — so your station and duty hours are logged without checking in and out by hand.",
  body: [
    "When you cross one of those locations, B4C checks your location at that moment to confirm you were really there, then records an arrival or departure event. It does not follow you between those moments.",
    "This is optional, used only for department-enabled attendance and service-hour features. It does not track your routes, driving, destinations, or off-duty activity, and your location is never sold.",
    "You can turn this off any time in Settings.",
  ],
  policy: { label: "Read the full Background Location Policy", href: "https://b4thecall.com/legal/background-location-policy" },
  accept: "Continue",
  decline: "Not now",
};

/* NEW MEMBER-FACING COPY, and it needs the same sign-off as the panel above.

   Android 11+ will not put "Allow all the time" in the same dialog as the first location
   prompt. It sends the member to a Settings page instead, and this is the explanation
   shown before that happens — the last thing they read before the OS stops explaining
   anything. Worded from the approved disclosure rather than invented, but it is still
   consent-adjacent text that no attorney has seen, so it lives under the same guard. */
const GEOFENCE_RATIONALE = {
  title: "Allow location all the time?",
  message: "B4C records arrivals and departures at your department's approved locations, even when the app is closed. To let it do that, choose \"Allow all the time\" on the next screen.",
  positiveAction: "Open settings",
  negativeAction: "Not now",
};

// Guard rail, now cleared. The assembled screen has been signed off by counsel, so the
// "awaiting legal sign-off" banner no longer renders. The mechanism stays in place: any
// future change to the disclosure wording, or to what the app actually does with location,
// puts this back to TRUE until the changed screen is reviewed again. Consent copy that
// drifts from behaviour is the failure this exists to catch.
const GEOFENCE_COPY_IS_DRAFT = false;

/* `onDecision` / `onWithdraw` let the caller do the native work (ask the OS, stop the
   plugin) while this panel stays responsible only for the copy and the record. When they
   are absent the panel is still self-contained and reviewable on its own — which is how
   G4b shipped and how it stays previewable in a browser.

   `permission` is what the OS actually says, passed in by the caller. Settings has to be
   able to tell someone their phone is blocking this; a screen that reports "on" while the
   OS quietly refuses is worse than one that reports nothing. */
function GeofenceDisclosure({ meId, notify, onBack, onDecision, onWithdraw, onEscalate, permission }) {
  const [consent, setConsent] = useState(() => readGeofenceConsent(meId));
  const [busy, setBusy] = useState(false);
  const [escalating, setEscalating] = useState(false);

  // Re-fire the Always request. Separate busy flag from `decide` so the escalation button
  // spins on its own rather than greying out the whole panel.
  async function escalate() {
    if (!onEscalate) return;
    setEscalating(true);
    try { await onEscalate(); } finally { setEscalating(false); }
  }

  // A decision we could not store would be re-asked on the next launch, which for
  // "granted" means a member thinks this is on when nothing is. Say so rather than
  // showing a success message that isn't true.
  async function decide(next) {
    const stored = writeGeofenceConsent(meId, next);
    if (!stored) {
      notify({ kind: "error", title: "Couldn't save that", text: "Your phone wouldn't let us store the choice, so we'll have to ask again next time." });
      return;
    }
    setConsent(next);
    if (onDecision) {
      // The caller owns the message from here: only it knows how the OS answered, and
      // two notifications for one tap is how you teach people to ignore them.
      setBusy(true);
      try { await onDecision(next); } finally { setBusy(false); }
      return;
    }
    notify(next === "granted"
      ? { kind: "success", title: "Automatic station presence is set up", text: "Your phone will ask for location access when this goes live." }
      : { kind: "success", title: "Left off", text: "Nothing changes — keep checking in by hand." });
  }

  async function withdraw() {
    if (!clearGeofenceConsent(meId)) {
      notify({ kind: "error", title: "Couldn't turn it off", text: "Your phone wouldn't let us update the choice. Try again." });
      return;
    }
    setConsent(null);
    if (onWithdraw) {
      setBusy(true);
      try { await onWithdraw(); } finally { setBusy(false); }
      return;
    }
    notify({ kind: "success", title: "Turned off", text: "Automatic station presence is off. Check in by hand as usual." });
  }

  const para = { fontSize: 13.5, color: FIRE.textSecondary, lineHeight: 1.6, margin: "0 0 12px" };

  return (
    <div>
      {/* The hub's copy of this rule lives in its own <style>, which this sub-screen doesn't
          render — without it the class is a dead hook and the link has no visible focus ring.
          A policy link that keyboard users can't see themselves land on is the wrong one to
          leave inaccessible. */}
      <style>{`.b4c-legal-link:focus-visible{outline:2px solid ${FIRE.blueText};outline-offset:2px;border-radius:6px}`}</style>
      <div style={NOIR_LABEL}>LOCATION</div>
      <h1 style={{ fontFamily: "'Oswald', system-ui, sans-serif", fontSize: 28, fontWeight: 700, color: FIRE.textPrimary, margin: "7px 0 12px", letterSpacing: "-0.01em" }}>
        {GEOFENCE_DISCLOSURE.title}
      </h1>

      {GEOFENCE_COPY_IS_DRAFT && (
        <div style={{ ...FS.cardNoir, padding: 14, marginBottom: 14, background: "rgba(214,169,94,.08)", border: "1px solid rgba(214,169,94,.32)" }}>
          <div style={{ display: "flex", gap: 9, alignItems: "flex-start" }}>
            <AlertTriangle size={16} color={FIRE.amberText} style={{ flexShrink: 0, marginTop: 1 }} />
            <div style={{ fontSize: 12.5, color: FIRE.textSecondary, lineHeight: 1.5 }}>
              <strong style={{ color: FIRE.textPrimary }}>Awaiting legal sign-off on this screen.</strong> The wording matches
              APP-002, but the assembled screen hasn't been cleared yet — it must not go in front of members or the app stores
              until it has.
            </div>
          </div>
        </div>
      )}

      <div style={{ ...FS.cardNoir, padding: 18 }}>
        {/* Paragraph 1 carries "even when the app is closed or not in use" — the statement the
            store looks for and the one a member most needs to actually read. Set apart so it
            cannot be skimmed past in a wall of text. The words are untouched. */}
        <div style={{ ...NOIR_INSET, padding: "13px 14px", margin: "0 0 14px", display: "flex", gap: 10, alignItems: "flex-start" }}>
          <MapPin size={17} color={FIRE.red} style={{ flexShrink: 0, marginTop: 1 }} />
          <div style={{ fontSize: 13.5, fontWeight: 600, color: FIRE.textPrimary, lineHeight: 1.55 }}>
            {GEOFENCE_DISCLOSURE.lead}
          </div>
        </div>

        {GEOFENCE_DISCLOSURE.body.map((line, i, arr) => (
          <p key={line} style={{ ...para, marginBottom: i === arr.length - 1 ? 0 : 12 }}>{line}</p>
        ))}
      </div>

      {/* The policy link sits between the copy and the buttons on purpose: a member deciding
          whether to agree should pass it on the way to the decision, not hunt for it after.
          Opens externally — leaving the app to read a policy must never cost someone the
          screen they were part-way through. */}
      <a href={GEOFENCE_DISCLOSURE.policy.href} target="_blank" rel="noopener noreferrer" className="b4c-legal-link"
         style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12, padding: "2px 2px", textDecoration: "none" }}>
        <ShieldAlert size={15} color={FIRE.red} style={{ flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 600, color: FIRE.textPrimary }}>{GEOFENCE_DISCLOSURE.policy.label}</span>
        <ExternalLink size={13} color={FIRE.textMuted} style={{ flexShrink: 0 }} />
      </a>

      {/* Answered already → show what they chose and let them change it. An agreement you
          cannot walk back is not consent, so "turn it off" is always on screen. */}
      {consent ? (
        <div style={{ ...FS.cardNoir, padding: 16, marginTop: 12 }}>
          <div style={{ display: "flex", gap: 9, alignItems: "flex-start" }}>
            {consent === "granted"
              ? <CheckCircle2 size={17} color={FIRE.greenText} style={{ flexShrink: 0, marginTop: 1 }} />
              : <Clock size={17} color={FIRE.textMuted} style={{ flexShrink: 0, marginTop: 1 }} />}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 13.5, fontWeight: 700, color: FIRE.textPrimary }}>
                {consent === "granted" ? "You turned this on for this phone." : "You left this off."}
              </div>
              {/* Report what the PHONE says, not what we asked for. Someone who tapped
                  Continue and then picked "While using the app" has agreed to something
                  that cannot actually work in the background, and the only useful thing
                  we can do is say so plainly and point at the setting that fixes it.
                  A half-grant shown as success is the failure people discover weeks later
                  when their hours are missing. */}
              <div style={{ fontSize: 12.5, color: FIRE.textSecondary, marginTop: 3, lineHeight: 1.5 }}>
                {consent !== "granted"
                  ? "Check in and out by hand as usual. You can change your mind here any time."
                  : permission === "when-in-use"
                    ? "Your phone is only allowing location while B4C is open, so arrivals and departures can't be recorded once you close it. Tap \"Allow in the background\" below and choose \"Change to Always Allow\" when your phone asks."
                    : permission === "denied" || permission === "restricted"
                      ? "Your phone is blocking location for B4C, so nothing can be recorded. You can change that in your phone's location settings."
                      : permission === "always"
                        ? "Your phone is allowing location all the time. Recording of arrivals and departures isn't switched on yet — nothing is being logged."
                        : "Nothing is recording yet. When this goes live, your phone will ask for location access first."}
              </div>
            </div>
          </div>
          <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
            {/* THE HALF-GRANT NEEDS A BUTTON, NOT INSTRUCTIONS. iOS does not list "Always" in
                Settings until the app has actually requested it, so telling a member to go and
                choose it sends them to a screen where the option is genuinely absent — which
                reads as the app being broken, or them being stupid, and neither is true.
                This re-fires the request so iOS shows its own "Change to Always Allow" prompt.
                Primary styling because it is the one thing standing between the member and the
                feature working; "Turn it off" steps back to secondary while it matters. */}
            {consent === "granted" && permission === "when-in-use" && onEscalate && (
              <button disabled={escalating || busy} onClick={escalate}
                      style={{ ...FS.btnPrimary, opacity: (escalating || busy) ? 0.6 : 1 }}>
                {escalating ? "Asking your phone…" : "Allow in the background"}
              </button>
            )}
            {consent === "granted"
              ? <button disabled={busy} onClick={withdraw} style={{ ...FS.btn, opacity: busy ? 0.6 : 1 }}>{busy ? "Turning off…" : "Turn it off"}</button>
              : <button disabled={busy} onClick={() => decide("granted")} style={{ ...FS.btnPrimary, opacity: busy ? 0.6 : 1 }}>{busy ? "Just a moment…" : GEOFENCE_DISCLOSURE.accept}</button>}
            {onBack && <button onClick={onBack} style={FS.btn}>Done</button>}
          </div>
        </div>
      ) : (
        // Never answered. Both choices are equally reachable and neither is preselected —
        // a store requirement, and the difference between asking and assuming.
        <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
          <button disabled={busy} onClick={() => decide("granted")} style={{ ...FS.btnPrimary, flex: "1 1 220px", opacity: busy ? 0.6 : 1 }}>{busy ? "Just a moment…" : GEOFENCE_DISCLOSURE.accept}</button>
          <button disabled={busy} onClick={() => decide("declined")} style={{ ...FS.btn, flex: "0 1 auto", opacity: busy ? 0.6 : 1 }}>{GEOFENCE_DISCLOSURE.decline}</button>
        </div>
      )}
    </div>
  );
}

/* The panel plus the native work behind it. Exists so Settings and the first-run overlay
   run the SAME flow — two copies of "ask the OS, then interpret the answer" would drift,
   and the one that drifted would be the one nobody was looking at. */
function GeofenceConsentFlow({ meId, notify, onBack, onDone }) {
  const [permission, setPermission] = useState(null);

  // What the OS says right now, asked without prompting. Web and flag-off return a reason
  // that isn't a permission state, so it stays null and the panel says nothing about it
  // rather than inventing a status.
  useEffect(() => {
    let alive = true;
    if (!geofenceAvailable()) return;
    getGeofencePermission().then((r) => {
      if (!alive) return;
      if (["always", "when-in-use", "denied", "restricted", "not-determined"].includes(r.reason)) setPermission(r.reason);
    });
    return () => { alive = false; };
  }, []);

  async function handleDecision(next) {
    if (next !== "granted") {
      // A refusal is a legitimate answer. It is recorded and never asked again — the
      // push.js rule, and the difference between asking someone once and nagging them.
      notify({ kind: "success", title: "Left off", text: "Nothing changes — keep checking in by hand. You can turn this on later in Settings." });
      onDone?.();
      return;
    }

    // Consent given somewhere the plugin cannot run (browser preview, flag off). The
    // record stands; the OS gets asked the first time this opens on a real device.
    if (!geofenceAvailable()) {
      notify({ kind: "success", title: "Saved", text: "Your phone will ask for location access when this goes live." });
      onDone?.();
      return;
    }

    const res = await requestGeofencePermission({ rationale: GEOFENCE_RATIONALE });
    if (["always", "when-in-use", "denied", "restricted"].includes(res.reason)) setPermission(res.reason);

    if (res.reason === "always") {
      notify({ kind: "success", title: "You're set up", text: "Your phone will let B4C record arrivals and departures. Nothing is being logged yet." });
    } else if (res.reason === "when-in-use") {
      // Deliberately an error: this LOOKS like success to the member and silently cannot
      // work. Left quiet, it surfaces weeks later as missing hours nobody can explain.
      notify({ kind: "error", title: "Only allowed while the app is open",
               text: "Arrivals and departures can't be recorded once you close B4C. Choose \"Allow all the time\" in your phone's location settings." });
    } else if (res.reason === "denied" || res.reason === "restricted") {
      notify({ kind: "error", title: "Location is blocked",
               text: "Your phone is blocking location for B4C. You can allow it in your phone's location settings, or keep checking in by hand." });
    } else {
      notify({ kind: "error", title: "Couldn't set that up", text: "Keep checking in by hand for now.", details: `${res.reason}${res.detail ? `: ${res.detail}` : ""}` });
    }
    onDone?.();
  }

  async function handleWithdraw() {
    // Stop first, then report. In G4c there is nothing running to stop, but the switch is
    // wired to the real call from the moment it appears so G4d doesn't inherit a button
    // that only pretends to work.
    const res = await stopGeofence();
    setPermission(null);
    if (!res.ok && !["web", "flag-off"].includes(res.reason)) {
      notify({ kind: "error", title: "Turned off, with a hitch", text: "Your choice is saved, but the phone didn't confirm it stopped.", details: `${res.reason}${res.detail ? `: ${res.detail}` : ""}` });
    } else {
      notify({ kind: "success", title: "Turned off", text: "Automatic station presence is off. Check in by hand as usual." });
    }
    onDone?.();
  }

  /* Re-ask for Always, for a member already sitting on the half-grant.
     Runs the SAME requestGeofencePermission as first-run, so the two-step escalation logic has
     exactly one definition. On iOS the second request is what makes the OS show "Change to
     Always Allow"; if the member has already refused that prompt once, iOS will not show it
     again and we fall through to telling them where the switch is — which by then genuinely
     EXISTS in Settings, because the request has now fired at least once. */
  async function handleEscalate() {
    const res = await requestGeofencePermission({ rationale: GEOFENCE_RATIONALE });
    if (["always", "when-in-use", "denied", "restricted"].includes(res.reason)) setPermission(res.reason);

    if (res.reason === "always") {
      notify({ kind: "success", title: "Background location is on",
               text: "Your phone will let B4C record arrivals and departures even when the app is closed." });
    } else if (res.reason === "when-in-use") {
      // Second refusal, or iOS declining to re-prompt. NOW the Settings instruction is honest:
      // the request has fired, so "Always" is actually listed on that screen.
      notify({ kind: "error", title: "Still limited to while the app is open",
               text: "Your phone didn't switch to background location. Open Settings → B4C → Location and choose \"Always\" — it will be listed there now." });
    } else if (res.reason === "denied" || res.reason === "restricted") {
      notify({ kind: "error", title: "Location is blocked",
               text: "Your phone is blocking location for B4C. You can allow it in Settings → B4C → Location, or keep checking in by hand." });
    } else {
      notify({ kind: "error", title: "Couldn't ask your phone", text: "Keep checking in by hand for now.",
               details: `${res.reason}${res.detail ? `: ${res.detail}` : ""}` });
    }
  }

  return <GeofenceDisclosure meId={meId} notify={notify} onBack={onBack}
                             onDecision={handleDecision} onWithdraw={handleWithdraw}
                             onEscalate={handleEscalate} permission={permission} />;
}

/* AFTER-CALL CHECKLIST — the department's setup screen. Slice 2: the toggle and the shared task
   list. No nav item, no member-facing run page and no history view yet; those are slice 3, and
   aftercall_log() is deliberately not called from here.

   TWO GATES, DELIBERATELY DIFFERENT, because they answer different questions:
     • WHO SEES THIS SCREEN and edits the list — canManage(): Board | Department Admin | Officer.
       It matches the is_canmanage() gate the slice 1 policies use, so the screen offers exactly
       what the server will accept. The owner reaches it as a Board Member.
     • WHO FLIPS THE FEATURE ON — isDeptAdmin(): Department Admin | Project Admin. Turning a
       feature on for a whole department is a different decision from maintaining its contents,
       and an Officer curating the list is not the same as an Officer deciding the department has
       the feature at all.
   A non-DA leader therefore sees the true state, read-only, and is told who can change it —
   rather than a control that would fail.

   THE LIST WRITES DIRECTLY TO aftercall_items under the slice 1 RLS. No RPC: the policies already
   say is_canmanage() AND department_id = my_department_id(), so the server is the authority and
   this screen only decides what to offer.

   EVERY WRITE USES .select() AND CHECKS FOR ZERO ROWS. A write REFUSED BY RLS comes back with no
   error and no rows — not an error — so treating a falsy `error` as success would show a member a
   task that was never saved. This is the same guard the apparatus checklist and the week-start
   setter use, for the same reason. */
function AfterCallSettings({ S, role, dept, setDept, notify }) {
  const isDA = isDeptAdmin(role);
  const enabled = !!dept?.aftercall_enabled;
  const [busyToggle, setBusyToggle] = useState(false);
  const [items, setItems] = useState(null);        // null = not loaded yet, [] = genuinely empty
  const [loadErr, setLoadErr] = useState("");
  const [adding, setAdding] = useState(false);
  const [label, setLabel] = useState("");
  const [busy, setBusy] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editBuf, setEditBuf] = useState("");

  /* RLS already confines this to the caller's own department, so no .eq("department_id") is
     needed — but sort_order IS load-bearing: it is the order crews will read the list in at 2am,
     and created_at breaks ties so two items added with the same order never swap around between
     loads. Retired items are excluded; they live on only inside past runs' snapshots. */
  const load = async () => {
    const { data, error } = await supabase.from("aftercall_items")
      .select("id, label, sort_order")
      .eq("active", true)
      .order("sort_order", { ascending: true }).order("created_at", { ascending: true });
    // A failed read is not an empty list. Keep whatever was on screen and say so, rather than
    // showing "no tasks yet" to a department that has twelve.
    if (error) { setLoadErr(error.message || "Please try again."); return; }
    setLoadErr(""); setItems(data || []);
  };
  useEffect(() => { if (enabled) load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [enabled]);

  async function toggle() {
    const next = !enabled;
    setBusyToggle(true);
    const { error } = await supabase.rpc("set_aftercall_enabled", { p_enabled: next });
    setBusyToggle(false);
    if (error) { notify?.({ kind: "error", title: "Couldn't change that setting", text: error.message || "Please try again." }); return; }
    setDept?.((d) => (d ? { ...d, aftercall_enabled: next } : d));
    notify?.({ kind: "success", text: next ? "After-Call Checklist is on for your department." : "After-Call Checklist is off. Nothing already logged was deleted." });
  }

  async function addItem() {
    const lbl = label.trim();
    if (!lbl) { notify?.({ kind: "error", title: "Give the task a name", text: "For example: “Wash the rig” or “Restock gloves”." }); return; }
    setBusy(true);
    const { data: deptId, error: deptErr } = await supabase.rpc("my_department_id");
    if (deptErr || !deptId) { setBusy(false); notify?.({ kind: "error", title: "Couldn't find your department", text: "Please try again.", details: deptErr?.message }); return; }
    // Appended at the end: a new task is the newest thing to do, not a re-ordering of the list
    // somebody else already put in an order that means something to them.
    const nextOrder = (items || []).reduce((mx, it) => Math.max(mx, it.sort_order ?? 0), -1) + 1;
    const { data, error } = await supabase.from("aftercall_items")
      .insert({ department_id: deptId, label: lbl, sort_order: nextOrder, active: true }).select();
    setBusy(false);
    if (error || !data || data.length === 0) { notify?.({ kind: "error", title: "Couldn't add that task", text: "It wasn't saved — please try again.", details: error?.message }); return; }
    setLabel(""); setAdding(false); load();
  }

  async function saveEdit(id) {
    const lbl = editBuf.trim();
    if (!lbl) { notify?.({ kind: "error", title: "Give the task a name", text: "A task needs a name crews will recognise." }); return; }
    setBusy(true);
    const { data, error } = await supabase.from("aftercall_items").update({ label: lbl }).eq("id", id).select();
    setBusy(false);
    if (error || !data || data.length === 0) { notify?.({ kind: "error", title: "Couldn't save that task", text: "It wasn't changed — please try again.", details: error?.message }); return; }
    setEditingId(null); load();
  }

  /* RETIRE, NEVER DELETE. Slice 1 copies the label onto every run at the moment it is logged, so
     a past run keeps reading exactly as it did — but that is only half of it. The row stays so the
     department can still see the task existed; deleting it would remove the only evidence outside
     those snapshots. The confirm says what actually happens, because "remove" reads like erasure. */
  async function retire(it) {
    if (!(await noirConfirm({ title: `Remove “${it.label}”?`, body: "Crews will stop seeing it. Checklists already logged keep it exactly as it was.", confirmLabel: "Remove", danger: true }))) return;
    setBusy(true);
    const { data, error } = await supabase.from("aftercall_items").update({ active: false }).eq("id", it.id).select();
    setBusy(false);
    if (error || !data || data.length === 0) { notify?.({ kind: "error", title: "Couldn't remove that task", text: "It's still on the list — please try again.", details: error?.message }); return; }
    load();
  }

  return (
    <PageShell band watermark="AFTER" kicker="AFTER-CALL CHECKLIST" title="After-Call Checklist"
      sub="A shared list of tasks crews complete after a call (wash, fuel, restock). Off by default.">
      <NoirSkin>

      {/* the toggle */}
      <div style={{ ...FS.cardNoir, padding: 18, marginBottom: 12, borderTop: `3px solid ${enabled ? FIRE.greenText : FIRE.amberText}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
          <span style={{ width: 38, height: 38, borderRadius: 10, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, background: `${FIRE.amberText}22`, border: `1px solid ${FIRE.amberText}44` }}><ClipboardCheck size={19} color={FIRE.amberText} /></span>
          <div style={{ flex: 1, minWidth: 180 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, fontWeight: 600, color: FIRE.textPrimary }}>
              {enabled ? "On for your department" : "Off"}
              <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", borderRadius: 5, padding: "2px 6px", color: enabled ? FIRE.greenText : FIRE.textMuted, border: `1px solid ${enabled ? `${FIRE.greenText}66` : FIRE.line2Noir}` }}>{enabled ? "Live" : "Off by default"}</span>
            </div>
            <div style={{ fontSize: 12.5, color: FIRE.textMuted, marginTop: 3, lineHeight: 1.5 }}>
              {enabled
                ? "Crews can log a checklist after a call."
                : "Nobody sees the checklist until this is on."}
            </div>
          </div>
          {isDA ? (
            <button disabled={busyToggle} onClick={toggle} aria-pressed={enabled} aria-label={enabled ? "Turn the After-Call Checklist off" : "Turn the After-Call Checklist on"}
                    style={{ display: "inline-flex", alignItems: "center", gap: 10, background: "none", border: "none", cursor: busyToggle ? "default" : "pointer", fontFamily: "inherit", padding: 4, opacity: busyToggle ? 0.7 : 1 }}>
              <span style={{ fontSize: 12.5, fontWeight: 600, color: FIRE.textSecondary }}>{busyToggle ? "Saving…" : enabled ? "On" : "Off"}</span>
              <span aria-hidden="true" style={{ width: 46, height: 26, borderRadius: 999, position: "relative", transition: "background .15s", background: enabled ? FIRE.green : FIRE.card2Noir, border: `1px solid ${enabled ? FIRE.green : FIRE.line2Noir}` }}>
                <span style={{ position: "absolute", top: 2, left: enabled ? 22 : 2, width: 20, height: 20, borderRadius: 999, background: "#fff", transition: "left .15s" }} />
              </span>
            </button>
          ) : (
            /* Read-only for a leader who can curate the list but not switch the feature on.
               Naming who can is more use than a disabled button with no explanation. */
            <span style={{ fontSize: 12.5, color: FIRE.textMuted2, maxWidth: 260, lineHeight: 1.5 }}>
              Ask a Department Admin to turn this on.
            </span>
          )}
        </div>
        {/* Said plainly at the moment of the decision: turning it off is reversible and destroys
            nothing, which is exactly what someone hesitating over a toggle needs to know. */}
        {enabled && (
          <div style={{ fontSize: 12, color: FIRE.textMuted2, marginTop: 10, lineHeight: 1.5 }}>
            Turning it off hides the checklist. Anything already logged is kept.
          </div>
        )}
      </div>

      {/* the shared list — only once the feature is on */}
      {enabled && (
        <div style={{ ...FS.cardNoir, padding: "8px 0" }}>
          <CardHead icon={ClipboardCheck} title="The task list" count={items ? items.length : undefined} style={{ padding: "10px 14px 2px", marginBottom: 4 }} />
          <div style={{ fontSize: 12.5, color: FIRE.textMuted, lineHeight: 1.5, padding: "0 14px 10px" }}>
            One list for the whole department — every rig uses it. Crews tick these off after a call.
          </div>
          {loadErr && (
            <div style={{ ...NOIR_ERR, margin: "0 14px 10px" }}>
              Couldn&rsquo;t load the list: {loadErr}
            </div>
          )}
          {items === null && !loadErr && <div style={{ fontSize: 13, color: FIRE.textMuted, padding: "0 14px 12px" }}>Loading…</div>}
          {items !== null && items.length === 0 && !loadErr && (
            <div style={{ fontSize: 13.5, color: FIRE.textMuted, padding: "0 14px 12px", lineHeight: 1.5 }}>
              No tasks yet — add the things crews do after a call.
            </div>
          )}
          {(items || []).map((it, idx) => (
            <div key={it.id} style={{ padding: "10px 14px", borderTop: `1px solid ${FIRE.lineNoir}`, display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
              <span style={{ width: 24, height: 24, borderRadius: 7, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11.5, fontWeight: 700, color: FIRE.textSecondary, background: FIRE.card2Noir, border: `1px solid ${FIRE.line2Noir}`, ...FS.num }}>{idx + 1}</span>
              {editingId === it.id ? (<>
                <input style={{ ...FS.input, flex: 1, minWidth: 180 }} value={editBuf} autoFocus
                       onChange={(e) => setEditBuf(e.target.value)}
                       onKeyDown={(e) => { if (e.key === "Enter") saveEdit(it.id); if (e.key === "Escape") setEditingId(null); }} />
                <button disabled={busy} style={{ ...FS.btnPrimary, padding: "6px 12px", fontSize: 12.5, opacity: busy ? 0.7 : 1 }} onClick={() => saveEdit(it.id)}>Save</button>
                <button disabled={busy} style={{ ...FS.btn, padding: "6px 12px", fontSize: 12.5 }} onClick={() => setEditingId(null)}>Cancel</button>
              </>) : (<>
                <span style={{ flex: 1, minWidth: 140, fontSize: 13.5, color: FIRE.textPrimary }}>{it.label}</span>
                <button style={{ ...FS.btn, padding: "5px 9px" }} title="Rename this task"
                        onClick={() => { setEditingId(it.id); setEditBuf(it.label || ""); }}><Pencil size={13} color={FIRE.btnIcon} /></button>
                <button disabled={busy} style={{ ...FS.btn, padding: "5px 9px" }} title="Remove from the list"
                        onClick={() => retire(it)}><X size={13} color={FIRE.deleteRed} /></button>
              </>)}
            </div>
          ))}
          <div style={{ padding: "10px 14px", borderTop: `1px solid ${FIRE.lineNoir}` }}>
            {adding ? (
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                <input style={{ ...FS.input, flex: 1, minWidth: 180 }} value={label} autoFocus
                       placeholder="e.g. Wash the rig"
                       onChange={(e) => setLabel(e.target.value)}
                       onKeyDown={(e) => { if (e.key === "Enter") addItem(); if (e.key === "Escape") { setAdding(false); setLabel(""); } }} />
                <button disabled={busy} style={{ ...FS.btnPrimary, opacity: busy ? 0.7 : 1 }} onClick={addItem}>
                  {busy ? <><Loader2 size={15} className="spin" /> Adding…</> : "Add task"}
                </button>
                <button disabled={busy} style={FS.btn} onClick={() => { setAdding(false); setLabel(""); }}>Cancel</button>
              </div>
            ) : (
              <button style={{ ...FS.btn, width: "100%", justifyContent: "center", borderStyle: "dashed" }} onClick={() => setAdding(true)}><Plus size={15} /> Add a task</button>
            )}
          </div>
        </div>
      )}
      </NoirSkin>
    </PageShell>
  );
}

/* FORMER MEMBERS — DEPARTMENT ADMIN ONLY (not Project Admin, not officers). A former member's date is HR-sensitive: it
   lives in a locked table reached only through get_/set_member_termination, which re-check the caller server-side, and
   it is in no view (celebrations and the roster never carry it). It also closes the member's attendance window — the
   server refuses attendance on drills after it (sql/membership_window). Marking someone former also moves them off the
   active roster (status Inactive); Reactivate clears the date and puts them back. Attendance already recorded after
   the date is reported, never deleted here. There is no list RPC, so the list is one get_ per roster member. */
function FormerMembers({ S, members, setMembers, meId, notify }) {
  const roster = (members || []).filter(isAssignable);
  const rosterKey = roster.map((m) => m.id).join(",");
  const [terms, setTerms] = useState(null);       // Map member id -> date; null until the first successful read
  const [loadErr, setLoadErr] = useState(false);
  const [pick, setPick] = useState("");
  const [on, setOn] = useState("");
  const [busy, setBusy] = useState(null);
  useEditorOpen(!!pick || !!on);
  function load(isAlive = () => true) {
    setLoadErr(false);
    Promise.all(roster.map((m) => supabase.rpc("get_member_termination", { p_member: m.id })
      .then(({ data, error }) => { if (error) throw error; return [m.id, data || null]; })))
      .then((pairs) => { if (isAlive()) setTerms(new Map(pairs.filter(([, d]) => d))); })
      .catch(() => { if (isAlive()) setLoadErr(true); });   // a failed read keeps the last list — never "nobody has left"
  }
  useEffect(() => { let alive = true; load(() => alive); return () => { alive = false; }; }, [rosterKey]);
  const byId = new Map(roster.map((m) => [m.id, m]));
  const former = terms ? [...terms].map(([id, d]) => ({ m: byId.get(id), d })).filter((x) => x.m).sort((a, b) => b.d.localeCompare(a.d)) : [];
  const current = roster.filter((m) => !(terms && terms.has(m.id))).sort((a, b) => a.name.localeCompare(b.name));
  const leftAfterText = (name, n) => n > 0 ? ` ${name} is still marked present at ${n} drill${n === 1 ? "" : "s"} after that date — nothing was removed; take them off those rosters if they weren't there.` : "";
  async function markFormer() {
    const m = byId.get(pick);
    if (!m || !on) return;
    if (m.id === meId) { notify({ kind: "error", title: "Can't mark yourself", text: "Have another Department Admin do it." }); return; }
    if (!(await noirConfirm({ title: `Mark ${m.name} as a former member?`, body: `Attendance can't be recorded for them on drills after ${fmtLongDate(on)}, and they move off the active roster. Only Department Admins can see this date.`, confirmLabel: "Mark as former member", danger: true }))) return;
    setBusy(m.id);
    const { data, error } = await supabase.rpc("set_member_termination", { p_member: m.id, p_date: on });
    if (error) { setBusy(null); notify({ kind: "error", title: "Couldn't mark them as a former member", text: "Nothing was changed. Please try again.", details: error.message }); return; }
    setTerms((t) => new Map(t || []).set(m.id, on));
    const { error: e2 } = await supabase.from("members").update({ status: "Inactive" }).eq("id", m.id);
    setBusy(null);
    if (e2) { notify({ kind: "error", title: "Date saved, roster status didn't", text: `${m.name}'s former-member date is saved, but they're still on the active roster. Deactivate them from their member file.`, details: e2.message }); }
    else { setMembers?.((ms) => ms.map((x) => x.id === m.id ? { ...x, status: "Inactive" } : x)); notify({ kind: "success", text: `${m.name} is now a former member.${leftAfterText(m.name, Number(data?.attendance_after || 0))}` }); }
    setPick(""); setOn("");
  }
  async function reactivate(m) {
    if (!(await noirConfirm({ title: `Reactivate ${m.name}?`, body: "Their former-member date is cleared and they return to the active roster. Attendance can be recorded for them again.", confirmLabel: "Reactivate" }))) return;
    setBusy(m.id);
    const { error } = await supabase.rpc("set_member_termination", { p_member: m.id, p_date: null });
    if (error) { setBusy(null); notify({ kind: "error", title: "Couldn't reactivate them", text: "Nothing was changed. Please try again.", details: error.message }); return; }
    setTerms((t) => { const n = new Map(t || []); n.delete(m.id); return n; });
    const { error: e2 } = await supabase.from("members").update({ status: "Active" }).eq("id", m.id);
    setBusy(null);
    if (e2) { notify({ kind: "error", title: "Date cleared, roster status didn't", text: `${m.name} is no longer a former member, but is still marked inactive. Reactivate them from their member file.`, details: e2.message }); return; }
    setMembers?.((ms) => ms.map((x) => x.id === m.id ? { ...x, status: "Active" } : x));
    notify({ kind: "success", text: `${m.name} is back on the active roster.` });
  }
  return (
    <PageShell band kicker="ADMIN" title="Former members"
      sub="People who have left the department. Only Department Admins see this list or these dates.">
      <NoirSkin>
      <div style={{ ...FS.cardNoir, padding: 18, display: "flex", flexDirection: "column", gap: 12, maxWidth: 560 }}>
        <div style={{ fontFamily: DISPLAY_FONT, fontWeight: 700, fontSize: 15, color: FIRE.textPrimary }}>Mark someone as a former member</div>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "flex-end" }}>
          <label style={{ ...S.field, flex: "1 1 200px", minWidth: 0 }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Member</span>
            <select style={FS.input} value={pick} disabled={!terms} onChange={(e) => setPick(e.target.value)}>
              <option value="">— Choose —</option>
              {current.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
            </select></label>
          <label style={{ ...S.field, flex: "0 1 170px" }}><span style={{ ...S.fieldLabel, color: FIRE.textSecondary }}>Last day</span>
            <input type="date" style={FS.input} value={on} onChange={(e) => setOn(e.target.value)} /></label>
          <button style={FS.btnPrimary} disabled={!pick || !on || !!busy} onClick={markFormer}><UserX size={15} /> Mark as former member</button>
        </div>
        <div style={{ fontSize: 12, color: FIRE.textMuted, lineHeight: 1.45 }}>Drills up to and including their last day still count. After it, attendance can&rsquo;t be recorded for them.</div>
      </div>
      <SectionBar icon={UserX} label="Former members" count={terms ? former.length : null} />
      {loadErr && (
        <div style={{ ...NOIR_INSET, padding: "10px 14px", marginBottom: 10, fontSize: 12.5, color: FIRE.amberText, display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ flex: 1, minWidth: 0 }}>Couldn&rsquo;t load former members{terms ? " — showing the last list" : ""}.</span>
          <button style={{ ...FS.btn, padding: "5px 10px" }} onClick={() => load()}><RotateCcw size={13} /> Retry</button>
        </div>
      )}
      {!terms && !loadErr && <div style={{ fontSize: 13, color: FIRE.textMuted, padding: "6px 2px" }}>Loading…</div>}
      {terms && former.length === 0 && <EmptyState text="No former members on file." />}
      {terms && former.length > 0 && (
        <Card padding="4px 14px">
          {former.map(({ m, d }, i) => (
            <div key={m.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 0", borderBottom: i < former.length - 1 ? `1px solid ${FIRE.lineNoir}` : "none", flexWrap: "wrap" }}>
              <div style={{ flex: 1, minWidth: 160 }}>
                <div style={{ fontSize: 14, fontWeight: 600, color: FIRE.textPrimary }}>{m.name}</div>
                <div style={{ fontSize: 12, color: FIRE.textMuted, marginTop: 2 }}>Former member · last day {fmtLongDate(d)}</div>
              </div>
              <button style={{ ...FS.btn, padding: "6px 11px" }} disabled={!!busy} onClick={() => reactivate(m)}><RotateCcw size={13} /> {busy === m.id ? "Working…" : "Reactivate"}</button>
            </div>
          ))}
        </Card>
      )}
      </NoirSkin>
    </PageShell>
  );
}
