const rsDate = (ymd) => { if (!ymd) return ""; const d = new Date(`${String(ymd).slice(0, 10)}T12:00:00`); return isNaN(d) ? "" : d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); };
